code_template:
// Return 5 for RISC-V, 3 for ARM, 1 for x86
// (RISC-V = 5 letters conceptually)

fn main() -> Int {
  return 1;  // Assuming x86_64 for this exercise
}

solution:
#[cfg(target_arch = "riscv64")]
fn chip() -> Int { return 5; }

#[cfg(target_arch = "aarch64")]
fn chip() -> Int { return 3; }

#[cfg(target_arch = "x86_64")]
fn chip() -> Int { return 1; }

fn main() -> Int {
  return chip();
}
